//go:build googlepinyin && !pinyin_external

package pinyinengine

import _ "embed"

// Generated by make from the pinned, checksummed upstream text corpus. The
// architecture-independent gzip dictionary is gitignored rather than vendored.
//
//go:embed assets/dict_pinyin.txt.gz
var dictionary []byte

func dictionaryBytes() ([]byte, error) { return dictionary, nil }
